import io
import datetime
from typing import Dict, List, Any, Optional

from backend.models import ScanResult, Finding, SeverityLevel
from backend.reporting.compliance_mappings import (
    SOC2_CRITERIA_INFO,
    CWE_TO_SOC2_MAP,
    ISO27001_CONTROLS_INFO,
    CWE_TO_ISO27001_MAP,
)

LEGAL_AUDIT_DISCLAIMER = (
    "LEGAL NOTICE: This document is an automated technical control evaluation aid generated by SecOps Guardian. "
    "It is designed solely to assist engineering and compliance teams in identifying technical vulnerabilities "
    "mapped to security frameworks. This report DOES NOT constitute a certified audit, formal attestation, or "
    "third-party assurance opinion and does not replace an official audit conducted by an accredited CPA or ISO auditor."
)


class ComplianceEvaluator:
    @staticmethod
    def evaluate_soc2(scan_result: ScanResult) -> Dict[str, Any]:
        """Evaluates findings against SOC 2 Trust Services Criteria."""
        controls_status = {}
        pass_count = 0
        fail_count = 0
        review_count = 0

        # Group findings by SOC 2 criteria
        criteria_findings: Dict[str, List[Finding]] = {c: [] for c in SOC2_CRITERIA_INFO.keys()}

        for f in scan_result.findings:
            cwe = f.cwe_id or ""
            mapped_criteria = CWE_TO_SOC2_MAP.get(cwe, [])
            for crit in mapped_criteria:
                if crit in criteria_findings:
                    criteria_findings[crit].append(f)

        for crit, info in SOC2_CRITERIA_INFO.items():
            findings = criteria_findings.get(crit, [])
            if not findings:
                status = "Pass"
                pass_count += 1
            else:
                has_critical_or_high = any(
                    f.severity in (SeverityLevel.CRITICAL, SeverityLevel.HIGH) for f in findings
                )
                if has_critical_or_high:
                    status = "Fail"
                    fail_count += 1
                else:
                    status = "Needs Review"
                    review_count += 1

            controls_status[crit] = {
                "id": crit,
                "title": info["title"],
                "category": info["category"],
                "description": info["description"],
                "status": status,
                "findings": findings,
            }

        return {
            "framework": "SOC 2 Type II (Trust Services Criteria)",
            "controls": controls_status,
            "pass_count": pass_count,
            "fail_count": fail_count,
            "review_count": review_count,
            "total_controls": len(SOC2_CRITERIA_INFO),
        }

    @staticmethod
    def evaluate_iso27001(scan_result: ScanResult) -> Dict[str, Any]:
        """Evaluates findings against ISO 27001:2022 Annex A Controls."""
        controls_status = {}
        pass_count = 0
        fail_count = 0
        review_count = 0

        control_findings: Dict[str, List[Finding]] = {c: [] for c in ISO27001_CONTROLS_INFO.keys()}

        for f in scan_result.findings:
            cwe = f.cwe_id or ""
            mapped_controls = CWE_TO_ISO27001_MAP.get(cwe, [])
            for c_id in mapped_controls:
                if c_id in control_findings:
                    control_findings[c_id].append(f)

        for c_id, info in ISO27001_CONTROLS_INFO.items():
            findings = control_findings.get(c_id, [])
            if not findings:
                status = "Pass"
                pass_count += 1
            else:
                has_critical_or_high = any(
                    f.severity in (SeverityLevel.CRITICAL, SeverityLevel.HIGH) for f in findings
                )
                if has_critical_or_high:
                    status = "Fail"
                    fail_count += 1
                else:
                    status = "Needs Review"
                    review_count += 1

            controls_status[c_id] = {
                "id": c_id,
                "title": info["title"],
                "clause": info["clause"],
                "description": info["description"],
                "status": status,
                "findings": findings,
            }

        return {
            "framework": "ISO/IEC 27001:2022 (Annex A Controls)",
            "controls": controls_status,
            "pass_count": pass_count,
            "fail_count": fail_count,
            "review_count": review_count,
            "total_controls": len(ISO27001_CONTROLS_INFO),
        }


# ==============================================================================
# Robust PDF Generation Engine
# ==============================================================================

def generate_compliance_pdf(evaluation: Dict[str, Any], scan_result: ScanResult, org_name: str) -> bytes:
    """
    Generates a professional compliance PDF report.
    Uses reportlab if available; falls back to pure-python compliant PDF generator.
    """
    try:
        from reportlab.lib.pagesizes import letter
        from reportlab.platypus import (
            SimpleDocTemplate,
            Paragraph,
            Spacer,
            Table,
            TableStyle,
            PageBreak,
            KeepTogether,
        )
        from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
        from reportlab.lib import colors

        buffer = io.BytesIO()
        doc = SimpleDocTemplate(
            buffer,
            pagesize=letter,
            rightMargin=40,
            leftMargin=40,
            topMargin=40,
            bottomMargin=40,
        )
        styles = getSampleStyleSheet()

        # Custom Styles
        title_style = ParagraphStyle(
            "CoverTitle",
            parent=styles["Normal"],
            fontName="Helvetica-Bold",
            fontSize=24,
            leading=28,
            textColor=colors.HexColor("#0f172a"),
            alignment=1,  # Center
        )
        subtitle_style = ParagraphStyle(
            "CoverSubtitle",
            parent=styles["Normal"],
            fontName="Helvetica",
            fontSize=13,
            leading=18,
            textColor=colors.HexColor("#475569"),
            alignment=1,
        )
        h2_style = ParagraphStyle(
            "SectionH2",
            parent=styles["Normal"],
            fontName="Helvetica-Bold",
            fontSize=16,
            leading=20,
            textColor=colors.HexColor("#1e293b"),
            spaceBefore=12,
            spaceAfter=8,
        )
        body_style = ParagraphStyle(
            "BodyDark",
            parent=styles["Normal"],
            fontName="Helvetica",
            fontSize=10,
            leading=14,
            textColor=colors.HexColor("#334155"),
        )
        disclaimer_style = ParagraphStyle(
            "LegalDisclaimer",
            parent=styles["Normal"],
            fontName="Helvetica-Oblique",
            fontSize=8,
            leading=11,
            textColor=colors.HexColor("#dc2626"),
            alignment=0,
        )

        elements = []

        # 1. Cover Page
        elements.append(Spacer(1, 80))
        elements.append(Paragraph("🛡️ SECOPS GUARDIAN", title_style))
        elements.append(Spacer(1, 10))
        elements.append(Paragraph("ENTERPRISE TECHNICAL COMPLIANCE REPORT", subtitle_style))
        elements.append(Spacer(1, 30))
        elements.append(Paragraph(f"<b>Framework:</b> {evaluation['framework']}", subtitle_style))
        elements.append(Paragraph(f"<b>Organization:</b> {org_name}", subtitle_style))
        elements.append(Paragraph(f"<b>Target Domain:</b> {scan_result.domain}", subtitle_style))
        elements.append(Paragraph(f"<b>Assessment Date:</b> {datetime.datetime.utcnow().strftime('%B %d, %Y')}", subtitle_style))
        elements.append(Paragraph(f"<b>Overall Security Grade:</b> {scan_result.grade} ({scan_result.score}/100)", subtitle_style))
        elements.append(Spacer(1, 60))

        # Legal Notice on Cover
        elements.append(Paragraph(f"<b>ATTENTION:</b> {LEGAL_AUDIT_DISCLAIMER}", disclaimer_style))
        elements.append(PageBreak())

        # 2. Executive Summary
        elements.append(Paragraph("1. Executive Compliance Summary", h2_style))
        summary_text = (
            f"This automated evaluation benchmarked the attack surface of <b>{scan_result.domain}</b> against "
            f"the <b>{evaluation['framework']}</b> standard. Out of <b>{evaluation['total_controls']}</b> core technical controls analyzed, "
            f"<b>{evaluation['pass_count']}</b> passed, <b>{evaluation['fail_count']}</b> failed, and "
            f"<b>{evaluation['review_count']}</b> require administrative review."
        )
        elements.append(Paragraph(summary_text, body_style))
        elements.append(Spacer(1, 15))

        # Summary Metrics Table
        metrics_data = [
            ["Metric", "Value", "Status Benchmark"],
            ["Total Evaluated Controls", str(evaluation["total_controls"]), "Baseline 100%"],
            ["Passed Controls", str(evaluation["pass_count"]), "Compliant"],
            ["Failed Controls", str(evaluation["fail_count"]), "Requires Urgent Remediation" if evaluation["fail_count"] > 0 else "Compliant"],
            ["Needs Review", str(evaluation["review_count"]), "Manual Review Required"],
        ]
        t_metrics = Table(metrics_data, colWidths=[200, 100, 200])
        t_metrics.setStyle(TableStyle([
            ('BACKGROUND', (0, 0), (-1, 0), colors.HexColor("#0f172a")),
            ('TEXTCOLOR', (0, 0), (-1, 0), colors.white),
            ('FONTNAME', (0, 0), (-1, 0), 'Helvetica-Bold'),
            ('FONTSIZE', (0, 0), (-1, 0), 10),
            ('BOTTOMPADDING', (0, 0), (-1, -1), 6),
            ('TOPPADDING', (0, 0), (-1, -1), 6),
            ('GRID', (0, 0), (-1, -1), 0.5, colors.HexColor("#cbd5e1")),
        ]))
        elements.append(t_metrics)
        elements.append(Spacer(1, 20))

        # 3. Control-by-Control Assessment Matrix
        elements.append(Paragraph("2. Technical Control Status Matrix", h2_style))
        matrix_data = [["Control ID", "Control Title", "Status", "Findings Count"]]
        for c_id, ctrl in evaluation["controls"].items():
            st = ctrl["status"]
            matrix_data.append([
                c_id,
                ctrl["title"],
                st,
                str(len(ctrl["findings"])),
            ])

        t_matrix = Table(matrix_data, colWidths=[80, 260, 90, 80])
        t_matrix.setStyle(TableStyle([
            ('BACKGROUND', (0, 0), (-1, 0), colors.HexColor("#1e293b")),
            ('TEXTCOLOR', (0, 0), (-1, 0), colors.white),
            ('FONTNAME', (0, 0), (-1, 0), 'Helvetica-Bold'),
            ('FONTSIZE', (0, 0), (-1, -1), 9),
            ('GRID', (0, 0), (-1, -1), 0.5, colors.HexColor("#cbd5e1")),
            ('TOPPADDING', (0, 0), (-1, -1), 5),
            ('BOTTOMPADDING', (0, 0), (-1, -1), 5),
        ]))
        elements.append(t_matrix)
        elements.append(PageBreak())

        # 4. Evidence Appendix
        elements.append(Paragraph("3. Technical Findings & Evidence Appendix", h2_style))
        if not scan_result.findings:
            elements.append(Paragraph("No technical vulnerabilities were flagged during this assessment.", body_style))
        else:
            for idx, f in enumerate(scan_result.findings, start=1):
                f_box = [
                    Paragraph(f"<b>Finding {idx}: {f.name}</b> (Severity: {f.severity})", body_style),
                    Paragraph(f"<b>Taxonomy:</b> {f.cwe_id or 'N/A'} | {f.owasp_category or 'N/A'}", body_style),
                    Paragraph(f"<b>Affected Endpoint:</b> <code>{f.endpoint}</code>", body_style),
                    Paragraph(f"<b>Remediation:</b> {f.remediation_summary}", body_style),
                ]
                if f.evidence:
                    f_box.append(Paragraph(f"<b>Evidence:</b> {f.evidence[:300]}", body_style))
                elements.extend(f_box)
                elements.append(Spacer(1, 10))

        doc.build(elements)
        return buffer.getvalue()

    except ImportError:
        # Self-contained pure Python PDF 1.4 generator fallback
        return _generate_minimal_pdf(evaluation, scan_result, org_name)


def _generate_minimal_pdf(evaluation: Dict[str, Any], scan_result: ScanResult, org_name: str) -> bytes:
    """Fallback generator producing valid standard PDF bytes without third-party dependencies."""
    pdf_text = (
        f"%PDF-1.4\n"
        f"1 0 obj << /Type /Catalog /Pages 2 0 R >> endobj\n"
        f"2 0 obj << /Type /Pages /Kids [3 0 R] /Count 1 >> endobj\n"
        f"3 0 obj << /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Contents 4 0 R /Resources << /Font << /F1 5 0 R >> >> >> endobj\n"
        f"5 0 obj << /Type /Font /Subtype /Type1 /BaseFont /Helvetica >> endobj\n"
    )

    content_stream = (
        "BT\n"
        "/F1 18 Tf\n"
        "50 740 Td\n"
        "(SECOPS GUARDIAN TECHNICAL COMPLIANCE REPORT) Tj\n"
        "/F1 12 Tf\n"
        "0 -30 Td\n"
        f"(Framework: {evaluation['framework']}) Tj\n"
        "0 -20 Td\n"
        f"(Organization: {org_name}) Tj\n"
        "0 -20 Td\n"
        f"(Target Domain: {scan_result.domain}) Tj\n"
        "0 -20 Td\n"
        f"(Score: {scan_result.score} / Grade: {scan_result.grade}) Tj\n"
        "0 -20 Td\n"
        f"(Passed Controls: {evaluation['pass_count']} | Failed: {evaluation['fail_count']} | Review: {evaluation['review_count']}) Tj\n"
        "0 -40 Td\n"
        "/F1 9 Tf\n"
        "(LEGAL NOTICE: Technical control mapping aid only - does not replace certified auditor assessment.) Tj\n"
        "ET\n"
    )

    stream_bytes = content_stream.encode("latin1")
    stream_len = len(stream_bytes)

    stream_obj = f"4 0 obj << /Length {stream_len} >> stream\n{content_stream}endstream\nendobj\n"
    
    body = pdf_text + stream_obj + "xref\n0 6\n0000000000 65535 f \n"
    trailer = "trailer << /Size 6 /Root 1 0 R >>\nstartxref\n9\n%%EOF"
    
    return (body + trailer).encode("latin1")
